def count_lines(s):
    if len(s) == 0:
        return 0
    return s.count("\n") + (0 if s.endswith("\n") else 1)

out = {}
total = 0
for p in ["data/a.txt", "data/b.txt"]:
    c = repo.read(p)
    n = count_lines(c)
    out[p] = n
    total += n
out["total"] = total
return out
